const triggerData = $('When Executed by Another Workflow').first().json;
const rawId = triggerData.task_id || new Date().toISOString().slice(0, 10).replace(/-/g, '') + '-research';
const researchText = $input.first().json.text || $input.first().json.output || '';
const verifyFlags = researchText.match(/\[VERIFY\]/gi) || [];

return [
  {
    json: {
      task_id: rawId,
      file_name: `${rawId}-sources.md`,
      verified_sources_markdown: researchText,
      unverified_count: verifyFlags.length
    }
  }
];

